let predictionChoice=null,grouping=null,challengeRenderKey='';let meta,state,program=[],roundKey='',dirty=false,version=0,busy=false,polling=false,revision=0,offset=0,selectedPair='',testRun=null,testAt=0,lastScene='',replayNodes=[],sound=true,lastFrame=-1,celebrated=false,settingUp=false,saveTimer,training=false,selectedStep=-1,debugStep=-1,lastCue='',trainingPausedAt=null,pairPickerKey='',fitCode=false,layoutFrame=0,lastLayoutKey='',reportKey='',shownReport=null;
