function openStep(i){if(!editable())return;selectedStep=i;const block=program[i],allowed=mission().blocks.includes('repeat');$('stepRepeat').disabled=!allowed;$('stepRepeat').title=allowed?'Replace this step with Repeat':'Repeat unlocks in round 3';$('stepError').textContent='';$('editRepeat').hidden=block.op!=='repeat'||!allowed;$('editRepeatCount').value=block.op==='repeat'?block.count:2;$('editRepeatOp').value=block.op==='repeat'?block.body[0].op:block.op==='collect'?'move':block.op;$('stepTitle').textContent='Step '+(i+1)+' · choose a block';$('earlier').disabled=i===0;$('later').disabled=i===program.length-1;$('stepEditor').showModal();}
