function countdownTone(seconds){if(!sound)return;try{const a=attention.unlock();if(!a)return;const o=a.createOscillator(),g=a.createGain(),duration=seconds===0?.55:.16;o.connect(g);g.connect(a.destination);o.frequency.setValueAtTime(seconds===0?220:650+(5-seconds)*90,a.currentTime);g.gain.setValueAtTime(.12,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+duration);o.start();o.stop(a.currentTime+duration+.01);}catch{}}
