async function request(opts){const r=await fetch(endpoint,opts),d=await r.json();if(!r.ok)throw Error(d.error||'Please try again.');return d;}
async function command(action,extra={}){if(busy)return false;busy=true;try{const d=await request({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,session:state?.id,round:state?.round,revision,...extra})});apply(d);$('status').textContent='';return true;}catch(e){if(action==='save'){try{apply(await request());if(state?.phase!=='build'||me()?.ready){if(me()?.ready)dirty=false;$('saveState').textContent=state?.phase==='paused'?'Paused · changes save when the game resumes.':'Code locked for the shared reveal.';return false;}}catch{}}$('status').textContent=e.message;return false;}finally{busy=false;}}
function sectionPayload(){const valid=grouping&&Number.isInteger(grouping.collect)&&(!state?.requireReturn||Number.isInteger(grouping.return));return state?.challenge?.kind==='sections'?{sections:valid?grouping:null}:{};}
async function save(){if(!dirty||busy||state?.phase!=='build')return;const v=version;const ok=await command('save',{program,...sectionPayload()});if(ok&&version===v){dirty=false;$('saveState').textContent='Program saved';}if(dirty)saveTimer=setTimeout(save,400);}
