function variantFor(id){return state?.pairs.some(p=>p.b===id)?'navigator':'captain';}
function avatarFor(id){return state?.players.find(p=>p.id===id)?.avatar||'neutral';}
function setVariant(el,variant,avatar='neutral'){if(el.dataset.variant!==variant)el.dataset.variant=variant;if(el.dataset.avatar!==avatar)el.dataset.avatar=avatar;}
