 if(block?.op==='repeat'){const before=blocks.slice(0,f.block).reduce((n,b)=>n+(b.op==='repeat'?b.count*b.body.length:1),0);iteration='↻ '+Math.min(block.count,Math.floor(Math.max(0,index-1-before)/block.body.length)+1)+' of '+block.count;}
